import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();
        long min_num = -1;
        long min_den = 1;
        for (long i = 1; i <= n; ++i) {
            long j = (i * x) / y;
            if ((i * x) - (j * y) > ((j + 1) * y) - (i * x))
                j++;
            long current_difference = Math.abs(i * x - j * y);
            long min_difference = Math.abs(min_num * y - x * min_den);
            if (min_num == -1 || (current_difference * min_den < min_difference * i))
                min_num = j;
                min_den = i;
        }
        System.out.println(min_num + "/" + min_den);
        scanner.close();
    }
}
